import os
import subprocess
import sys
import unittest
from decimal import Decimal, ROUND_HALF_UP

from invoice_engine import Invoice, InvoiceLine, TaxRate, calculate_totals

VAT = TaxRate("standard", Decimal("0.24"))
CENT = Decimal("0.01")


def _inv(*prices):
    return Invoice.from_lines("P-1", "Probe", [InvoiceLine("item", Decimal("1"), Decimal(p), VAT) for p in prices])


def _cents(x):
    return x.quantize(CENT, rounding=ROUND_HALF_UP)


class CountersignProbes(unittest.TestCase):
    def test_AC1_WelcomeFivePercentOfSmallSubtotal(self):
        # 5% of 0.10 = 0.005 -> 0.01 when rounded to cents; 5% of 3.30 = 0.165 -> 0.17
        for prices in (("0.10",), ("1.10", "1.10", "1.10")):
            r = calculate_totals(_inv(*prices), "WELCOME")
            self.assertEqual(r.discount, _cents(r.subtotal * Decimal("0.05")), prices)

    def test_AC2_PartnerTenPercentFromInclusive1000(self):
        r = calculate_totals(_inv("1000.00"), "PARTNER")
        self.assertEqual(r.discount, Decimal("100.00"))
        r = calculate_totals(_inv("600.00", "400.00"), "PARTNER")
        self.assertEqual(r.discount, Decimal("100.00"))
        r = calculate_totals(_inv("999.99"), "PARTNER")
        self.assertEqual(r.discount, Decimal("0.00"))

    def test_AC3_NonprofitFifteenPercentFromInclusive500(self):
        r = calculate_totals(_inv("500.00"), "NONPROFIT")
        self.assertEqual(r.discount, Decimal("75.00"))
        r = calculate_totals(_inv("800.00"), "NONPROFIT")
        self.assertEqual(r.discount, Decimal("120.00"))
        r = calculate_totals(_inv("499.99"), "NONPROFIT")
        self.assertEqual(r.discount, Decimal("0.00"))

    def test_AC4_CentRoundingAndTotalEqualsTaxablePlusTax(self):
        for code in ("WELCOME", "PARTNER", "NONPROFIT"):
            for prices in (("333.333", "333.337", "500.019"), ("0.07",), ("1234.565",)):
                r = calculate_totals(_inv(*prices), code)
                for v in (r.discount, r.tax, r.taxable, r.total):
                    self.assertEqual(v, v.quantize(CENT), (code, prices, v))
                self.assertEqual(r.total, r.taxable + r.tax, (code, prices))

    def test_AC6_ExistingSuiteStillPasses(self):
        here = os.path.dirname(os.path.abspath(__file__))
        files = [os.path.join(here, f) for f in ("test_totals.py", "test_rounding.py", "test_formatting.py")
                 if os.path.exists(os.path.join(here, f))]
        proc = subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", *files],
                              capture_output=True, text=True, cwd=os.path.dirname(here))
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)

